import csv
import io
import re


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    anchors = {
        "organisation name",
        "organisation code",
        "effective date",
        "supplier name",
        "purpose of spend",
    }

    def normalize(value):
        return re.sub(r"\s+", " ", value.strip().lower())

    header_index = None
    for index, row in enumerate(records):
        names = {normalize(value) for value in row if value.strip()}
        if len(names & anchors) >= 3:
            header_index = index
            break

    if header_index is None:
        candidates = records[:100]
        max_populated = max(
            (sum(bool(value.strip()) for value in row) for row in candidates),
            default=0,
        )
        if not max_populated:
            return {"columns": [], "rows": records}
        threshold = max(1, max_populated // 2)
        header_index = next(
            i for i, row in enumerate(candidates)
            if sum(bool(value.strip()) for value in row) >= threshold
        )

    header = records[header_index]
    rows = records[header_index + 1:]
    width = max([23, len(header)] + [len(row) for row in rows])

    reserved = {value.strip() for value in header if value.strip()}
    used = set()
    columns = []
    for i in range(width):
        base = header[i].strip() if i < len(header) else ""
        if not base:
            base = "column_" + str(i + 1)
            candidate = base
            suffix = 2
            while candidate in used or candidate in reserved:
                candidate = base + "_" + str(suffix)
                suffix += 1
        else:
            candidate = base
            suffix = 2
            while candidate in used:
                candidate = base + "_" + str(suffix)
                suffix += 1
        used.add(candidate)
        columns.append(candidate)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
